{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C45"],
      "claim": "Tolfenamic acid, the highest-transfer analogue, has absolute oral bioavailability of 61.6% in healthy volunteers, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Encainide, a close-transfer amide/aryl ether with a saturated basic heterocycle, shows 32 ± 7% absolute oral bioavailability in normal subjects, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Meloxicam, a heteroaromatic amide with high transferability, has absolute oral bioavailability of 89%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Isradipine, a structurally dissimilar dihydropyridine ester, has systemic availability of only 16.5% in volunteers, providing a contradictory low-F anchor but with lower structural relevance to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C55"],
      "claim": "Esaxerenone, a high-transfer modern oral drug, has absolute bioavailability of 89% in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Glasdegib, which shares amide/urea, pyridine, and saturated N-heterocycle features, has absolute oral bioavailability of 77.12%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Nilotinib, sharing amide/pyridine/trifluoromethylaryl features, has an estimated absolute bioavailability of 17% at 400 mg, a contradictory low-F anchor; however, its BCS IV solubility limitation may not transfer to the morpholine-containing query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C40"],
      "claim": "Elinzanetant, structurally similar as a biaryl amide/pyridine with trifluoromethylphenyl and saturated heterocycle, has oral bioavailability of 36.7%, above the 20% threshold and supportive of high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of high-transfer experimental evidence indicates oral bioavailability above 20%: multiple structurally relevant amide/heteroaryl drugs show F from 36.7% to 89%, while the low-F anchors are either structurally distant or limited by solubility issues not clearly shared by the query. Therefore predict high.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule.",
    "Human pharmacokinetic data, solubility, permeability, and first-pass metabolism status are unknown.",
    "A nilotinib-like solubility limitation cannot be fully excluded for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

